{"action":"tool","tool":"python_exec","args":{"code":"import pandas as pd

cols = list(df.columns)
clinic_col = None
recovered_col = None
total_col = None
rate_col = None
for c in cols:
    cl = c.lower()
    if clinic_col is None and 'clinic' in cl:
        clinic_col = c
    if recovered_col is None and 'recover' in cl and 'rate' not in cl:
        recovered_col = c
    if total_col is None and (cl in ['total', 'patients', 'count', 'cases', 'visits'] or ('total' in cl and 'recover' not in cl)):
        total_col = c
    if rate_col is None and 'rate' in cl:
        rate_col = c

if clinic_col is None:
    raise ValueError(f'Could not find clinic column in {cols}')

work = df.copy()
if rate_col is not None:
    work[rate_col] = pd.to_numeric(work[rate_col], errors='coerce')
    best_idx = work[rate_col].idxmax()
    row = work.loc[best_idx]
    print({'clinic_col': clinic_col, 'rate_col': rate_col, 'row': row.to_dict()})
else:
    if recovered_col is None or total_col is None:
        raise ValueError(f'Could not find sufficient columns in {cols}')
    work[recovered_col] = pd.to_numeric(work[recovered_col], errors='coerce')
    work[total_col] = pd.to_numeric(work[total_col], errors='coerce')
    work['_rate'] = work[recovered_col] / work[total_col]
    best_idx = work['_rate'].idxmax()
    row = work.loc[best_idx]
    print({'clinic_col': clinic_col, 'recovered_col': recovered_col, 'total_col': total_col, 'row': row.to_dict()})"}}
